{
  "opening": "This release focuses on aligning boltons with modern Python standards, particularly regarding dictionary ordering in Python 3.7+, while introducing new utility classes for set operations, bit manipulation, and frozen mappings. It also ensures backward compatibility efforts for older Python versions are maintained where feasible.",
  "requirements": [
    {
      "id": "m09",
      "text": "The public API functions and classes including SequentialGUIDerator, construct_format_field_str, daterange, get_format_args, and wrap_trace must continue to function correctly without regression."
    },
    {
      "id": "m12",
      "text": "OrderedMultiDict must no longer support the documented use case of constructing an instance via dict(omd), as this behavior is incompatible with Python 3.7+ dictionary ordering guarantees."
    },
    {
      "id": "m22",
      "text": "The library must operate without any unnecessary imports that do not contribute to the public API or internal functionality."
    },
    {
      "id": "m23",
      "text": "The URL class must provide a __str__ method that returns a string representation of the URL equivalent to the output of to_text."
    },
    {
      "id": "m28",
      "text": "IndexedSet must implement standard set-like methods including add, complement, complemented, difference, difference_update, discard, intersection, isdisjoint, issubset, issuperset, pop, remove, symmetric_difference, symmetric_difference_update, union, and update."
    },
    {
      "id": "m30",
      "text": "LRU and LRI cache classes must correctly handle clear, copy, get, setdefault, and update operations without data corruption or performance issues."
    },
    {
      "id": "m31",
      "text": "The Bits class must provide conversion methods as_bin, as_bytes, as_hex, as_int, as_list, floor, from_bin, from_bytes, from_hex, from_int, and from_list to facilitate binary and integer manipulations."
    },
    {
      "id": "m33",
      "text": "ManyToMany and OneToOne must work alongside OrderedMultiDict, supporting operations such as add, get, iteritems, keys, remove, replace, subdict, and update for managing many-to-many relationships."
    },
    {
      "id": "m34",
      "text": "FrozenDict and FrozenHashError must be available, with FrozenDict supporting fromkeys, subdict, and updated methods to create immutable dictionary variants."
    }
  ],
  "closing": "Please ensure all changes are verified against supported Python versions to maintain compatibility across the board."
}
